arrayComuni.forEach(comune => {
  var item = document.querySelector('.comune-template').cloneNode(true).content;
  item.querySelector('.nome-comune').innerText = comune;

  item.querySelector('input[type="checkbox"]').addEventListener('change', function () {
    if (this.checked) {
      console.log(comune);
      applyCityBorder(map, comune);
    }
    else {
      console.log("tolto " + comune);
      comuniSelezionati[comune].remove();
      delete comuniSelezionati[comune]
    }

  });
  document.getElementById('lista-comuni').appendChild(item);
});

