function applyCityBorder(map, cityname) {
  if (cityname == 'Arzano' || cityname == 'Calvi' || cityname == 'Corbara' || cityname == 'Liveri' || cityname == 'Montoro' || cityname == 'Salento') {
    jQuery
      .ajax({
        type: "GET",
        dataType: "json",
        url:
          "https://nominatim.openstreetmap.org/search?q=" +
          cityname.toLowerCase().trim() +
          "+Campania&polygon_geojson=1&format=json"
      })
      .then(function (data) {
        comuniSelezionati[cityname] = L.geoJSON(data[0].geojson, {
          color: "#80b2f6",
          weight: 3,
          opacity: 1,
          fillOpacity: 0.4
        })
        comuniSelezionati[cityname].addTo(ComuniGroup);
      });
  }
  else {
    jQuery
      .ajax({
        type: "GET",
        dataType: "json",
        url:
          "https://nominatim.openstreetmap.org/search?city=" +
          cityname.toLowerCase().trim() +
          "&polygon_geojson=1&format=json"
      })
      .then(function (data) {
        comuniSelezionati[cityname] = L.geoJSON(data[0].geojson, {
          color: "#80b2f6",
          weight: 3,
          opacity: 1,
          fillOpacity: 0.4
        })
        comuniSelezionati[cityname].addTo(ComuniGroup);
      });
  }
}


function applyCountryBorder(map, countryname) {
  jQuery
    .ajax({
      type: "GET",
      dataType: "json",
      url:
        "https://nominatim.openstreetmap.org/search?state=" +
        countryname.trim() +
        "&polygon_geojson=1&format=json"
    })
    .then(function (data) {
      L.geoJSON(data[0].geojson, {
        color: "red",
        weight: 3,
        opacity: 1,
        fillOpacity: 0.0
      }).addTo(map);
    });
}



// Zoom Control
var zoomControl = L.control.zoom({
  position: "bottomright"
});
zoomControl.addTo(map);

// Leaflet Draw
var drawnItems = new L.FeatureGroup();
map.addLayer(drawnItems);
var drawControl = new L.Control.Draw({
  position: "bottomleft",
  edit: {
    featureGroup: drawnItems,
    poly: {
      allowIntersection: false
    }
  },
  draw: {

    marker: false,
    polyline: false,
    circle: false,
    circlemarker: false,
    polygon: {
      allowIntersection: false,
      showArea: true
    }
  }
});
map.addControl(drawControl);

// Truncate value based on number of decimals
var _round = function (num, len) {
  return Math.round(num * (Math.pow(10, len))) / (Math.pow(10, len));
};
// Helper method to format LatLng object (x.xxxxxx, y.yyyyyy)
var strLatLng = function (latlng) {
  return "(" + _round(latlng.lat, 6) + ", " + _round(latlng.lng, 6) + ")";
};

// Generate popup content based on layer type
// - Returns HTML string, or null if unknown object
var getPopupContent = function (layer) {
  // Marker - add lat/long
  if (layer instanceof L.Marker || layer instanceof L.CircleMarker) {
    return strLatLng(layer.getLatLng());
    // Circle - lat/long, radius
  } else if (layer instanceof L.Circle) {
    var center = layer.getLatLng(),
      radius = layer.getRadius();
    return "Center: " + strLatLng(center) + "<br />"
      + "Radius: " + _round(radius, 2) + " m";
    // Rectangle/Polygon - area
  } else if (layer instanceof L.Polygon) {
    var latlngs = layer._defaultShape ? layer._defaultShape() : layer.getLatLngs(),
      area = L.GeometryUtil.geodesicArea(latlngs);
    return "Area: " + L.GeometryUtil.readableArea(area, true);
    // Polyline - distance
  } else if (layer instanceof L.Polyline) {
    var latlngs = layer._defaultShape ? layer._defaultShape() : layer.getLatLngs(),
      distance = 0;
    if (latlngs.length < 2) {
      return "Distance: N/A";
    } else {
      for (var i = 0; i < latlngs.length - 1; i++) {
        distance += latlngs[i].distanceTo(latlngs[i + 1]);
      }
      if (_round(distance, 2) > 1000) {
        return "Distance: " + _round(distance, 2) / 1000 + " km"; // kilometers
      } else {
        return "Distance: " + _round(distance, 2) + " m"; // meters
      }
    }
  }
  return null;
};

// Object created - bind popup to layer, add to feature group
map.on(L.Draw.Event.CREATED, function (event) {
  var layer = event.layer;
  var content = getPopupContent(layer);
  if (content !== null) {
    layer.bindPopup(content);
  }

  // Add info to feature properties
  feature = layer.feature = layer.feature || {};
  feature.type = feature.type || "Feature";
  var props = feature.properties = feature.properties || {}; // Intialize feature.properties
  props.info = content;
  drawnItems.addLayer(layer);
  // console.log(JSON.stringify(drawnItems.toGeoJSON()));
});

// Object(s) edited - update popups
map.on(L.Draw.Event.EDITED, function (event) {
  var layers = event.layers,
    content = null;
  layers.eachLayer(function (layer) {
    content = getPopupContent(layer);
    if (content !== null) {
      layer.setPopupContent(content);
    }

    // Update info to feature properties
    var layer = layer;
    feature = layer.feature = layer.feature || {};
    var props = feature.properties = feature.properties || {};
    props.info = content;
  });
  console.log(JSON.stringify(drawnItems.toGeoJSON()));
});

// Object(s) deleted - update console log
map.on(L.Draw.Event.DELETED, function (event) {
  console.log(JSON.stringify(drawnItems.toGeoJSON()));
});


