function mostraListaComuni() {
  //posiziona//
  let butt = document.getElementById("butSelezionaComune")
  var buttRect = butt.getBoundingClientRect()
  let nav = document.getElementById("navListaComuni")
  var navRect = nav.getBoundingClientRect()
  var toppp = buttRect.top + buttRect.height;
  nav.style.top = `${toppp + 10}px`;
  nav.style.left = `${buttRect.left}px`;
  ///////////

  if (nav.classList[0] == "nascondiListaComuni") {
    nav.classList.remove("nascondiListaComuni")
    nav.classList.add("visualizzaListaComuni")
  }
  else {
    nav.classList.remove("visualizzaListaComuni")
    nav.classList.add("nascondiListaComuni")
  }
}

document.addEventListener("click", function (event) {
  const targetElement = event.target; // elemento che ha scatenato l'evento click
  if (targetElement !== document.getElementById('butSelezionaComune') && targetElement !== document.getElementById('navListaComuni') && !document.getElementById('navListaComuni').contains(targetElement)) {
    document.getElementById('navListaComuni').classList.remove("visualizzaListaComuni")
    document.getElementById('navListaComuni').classList.add("nascondiListaComuni")
  }
});

