function calcolaValore() {
  var valoreMonetario = document.getElementById('testoValore').value;
  var valoreTotale = 0
  if (/^(\d+,)*(\d+)$/.test(valoreMonetario)) {
    valoreTotale = parseInt(valoreMonetario) * co2assorbita
    root = document.getElementById('valoreTotaleCalcolato');
    root.innerHTML = "<strong>Il valore monetario totale è di " + (Math.floor(valoreTotale)).toLocaleString('it-IT', { style: 'currency', currency: 'EUR' }) + '</strong><p><button id="butstampadettagli" type="button" onclick="generaPDF()" class="btn btn-success btn-sm text-light mt-3">Stampa dettagli</button></p>'
  }
  else {
    alert("Il valore inserito non è corretto!")
  }
}



