//vede i comuni che intersecano i poligoni///////////////////////
function mostraComuniInteressati() {
  var textComuniIntersecati = JSON.parse('{  "type": "FeatureCollection", "features": []}');
  var copiaCampania = JSON.parse(JSON.stringify(campaniaGeojson2));

  if (layerComuniIntersecati != null) {
    map.removeLayer(layerComuniIntersecati)
  }
  arrayComuniIntersecati.forEach(intersecato => {
    let comuneIndex = copiaCampania.features.findIndex(comune => comune.properties.COMUNE == intersecato);
    if (comuneIndex != -1) {
      textComuniIntersecati.features.push(copiaCampania.features[comuneIndex].geometry);
      copiaCampania.features.splice(comuneIndex, 1);
    }
  });
  layerComuniIntersecati = L.geoJSON(textComuniIntersecati, {
    style: {
      color: 'black',
      fillOpacity: 0,
      weight: 1.0
    }
  });
  layerComuniIntersecati.addTo(map);
  document.getElementsByClassName('loading')[0].classList.remove('visible');
  document.getElementById("butSelezionaComune").removeAttribute("disabled");
  document.getElementById("mostraInfoBut").removeAttribute("disabled");
  document.getElementById("eseguiClipBut").removeAttribute("disabled");
  document.getElementById("navListaComuni").removeAttribute("hidden");
  document.getElementById("bottonePoligoni").removeAttribute("hidden");
  document.getElementById("bottoneRettangoli").removeAttribute("hidden");
  document.getElementById("bottoneEditaPoligoni").removeAttribute("hidden");
  document.getElementById("bottoneEliminaPoligoni").removeAttribute("hidden");
  document.getElementById("bottoneZoomIn").removeAttribute("hidden");
  document.getElementById("bottoneZoomOut").removeAttribute("hidden");
  document.getElementById("infoApp").removeAttribute("disabled");
}
